validation.command:
@'
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { loadPackageFromDirectory, validatePackage } from '@jvm-expert/core';
import { NodeFileSystem } from '@jvm-expert/node';
import { ClaudeCodeAdapter } from '@jvm-expert/adapter-claude';
import { CodexAdapter } from '@jvm-expert/adapter-codex';
const directory = resolve('skills/idempotency');
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), directory, { strict: true });
const report = validatePackage(loaded.pkg, {
  strict: true, directoryName: 'idempotency',
  adapters: [new ClaudeCodeAdapter(), new CodexAdapter()],
});
const issues = [...loaded.issues, ...report.issues];
assert.deepEqual(issues, []);
assert.equal(loaded.pkg.manifest.version, '1.2.5');
const declared = new Set([
  ...(loaded.pkg.manifest.dependencies ?? []).map(item => item.name),
  ...(loaded.pkg.manifest.suggests ?? []),
]);
const referrals = new Set();
let localMarkdownLinks = 0;
for (const file of loaded.pkg.files.filter(file => file.path.endsWith('.md'))) {
  const content = readFileSync(resolve(directory, file.path), 'utf8');
  for (const match of content.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)) {
    if (/^https?:/.test(match[1])) continue;
    const [target, anchor] = match[1].split('#');
    const absolute = resolve(directory, dirname(file.path), target);
    assert.ok(existsSync(absolute), file.path + ': ' + match[1]);
    if (anchor === 'one-incoming-intent-several-downstream-effects') {
      assert.ok(readFileSync(absolute, 'utf8').includes('## One incoming intent, several downstream effects'));
    }
    localMarkdownLinks++;
  }
  for (const match of content.matchAll(/`([a-z][a-z0-9]*-[a-z0-9-]+)`/g)) {
    const name = match[1];
    if (!existsSync(resolve('skills', name, 'SKILL.md'))) continue;
    assert.ok(declared.has(name), 'Undeclared referral: ' + name);
    referrals.add(name);
  }
}
console.log(JSON.stringify({
  status: 'PASS', name: loaded.pkg.manifest.name, version: loaded.pkg.manifest.version,
  files: loaded.pkg.files.length, issues: issues.length, localMarkdownLinks,
  declaredSkillReferrals: referrals.size, adapters: ['claude', 'codex'],
}));
'@ | node --input-type=module
